\section{Algorithm of Entire Procedure}
\label{sec:algorithm-of-entire-procedure}
We provide the PyTorch-like pseudocode of layer-wise curriculum learning with feature caching using a multi-threading strategy in \cref{alg:curriculum_know_transfer} to facilitate understanding the entire procedure.
The detailed algorithm is described as follows:
\begin{enumerate}
    \item Partitioning:
    Divide the teacher and student models into $K$ segments.
    Each segment is treated as the basic optimization unit of the layer-wise knowledge transfer procedure.
    For the student model, each segment typically includes a single student layer.
    \item Feature caching from teacher: 
    Forward the teacher model only once to extract intermediate features for all segments.
    These cached teacher features are reused during training as fixed label features.
    The curriculum features are set to the teacher cache at the initial step ($t\!\!\!=\!\!\!0$).
    For large models such as LLaMA-family~\cite{touvron2023llama,grattafiori2024llama} and Qwen~\cite{yang2024qwen25}, the cached features are compressed with LLM.int8()~\cite{10.5555/3600270.3602468} quantization to reduce storage overhead.
    \item Multi-threaded knowledge transfer:
    Each active layer $k \ge \psi(t)$ is assigned to a dedicated device.
    Each worker reads the corresponding cached curriculum and label features, computes the cosine loss, and updates the parameters of the layer.
    Since active layers are independent, their knowledge transfer can be executed in parallel with multi-threading.
    \item Progressive freeze:
    At each curriculum transition, freeze the shallowest active student layer.
    This progressively increases the minimum active depth $\psi(t)$, reallocating the optimization budget from already-converged layers to deeper, more error-prone ones.
    \item Efficient cache update:
    Update the curriculum features using the current student model, but recompute only the active layers.
    The cached outputs of the frozen ones are reused, which avoids redundant forward passes and preserves computational efficiency.
    \item Iteration:
    Repeat the 3) multi-threaded knowledge transfer, 4) progressive freezing, and 5) efficient cache updating until all layers have been optimized and frozen.
    \item Short recovery:
    After the layer-wise knowledge transfer, perform a very short end-to-end recovery stage with LoRA~\cite{hu2022lora} adapters on student model.
    This stage refines alignment across layers at low additional cost by updating only a small set of trainable adapter parameters.
\end{enumerate}


\begin{algorithm*}[t!]
\DontPrintSemicolon
\begin{lstlisting}[basicstyle=\ttfamily\footnotesize]
# Assume 1: n_T > n_S (teacher segments contain more layers than student segments)
# K : Number of segments
# x : Input data
from threading import Thread as thr

# Split teacher and student models into K segments
f_T = [Teacher(layers=k*n_T to (k+1)*n_T) for k in range(K)]
f_S = [Student(layers=k*n_S to (k+1)*n_S) for k in range(K)]

# Cache(update) forward-propagated features
def feature_cache(x, segments, cache_h=None, start_k=0):                 
    if cache_h is None:                 # Initialization
        cache_h = [None] * (K+1)        
        cache_h[0] = x

    h = cache_h[start_k]
    for k in range(start_k, K):         # Iteration for active segments
        h = segments[k](h)              # Forward propagation
        cache_h[k+1] = h                # Cache propagated features
    return cache_h

# Knowledge transfer of each layer
def know_transfer(k, pair_h):           
    h_curr = pair_h['curr'][k]          # Load cached curriculum/label features
    h_label = pair_h['label'][k+1]       
    h_output = f_S[k](h_curr)           # Forward with curriculum features
    L_kd = cosine_loss(h_label, h_output)   
    L_kd.backward()                     
    optimizer_layers[k].step()          # Update student layer

teacher_h = feature_cache(x, f_T)       # Initialize curriculum/label features
pair_h = {'curr': teacher_h, 'label': teacher_h}
del f_T                                 # Decommission teacher model

for psi_t in range(K):                  # Curriculum Schedule for active layers
    thrds = [thr(target=know_transfer, args=(k, pair_h)) for k in range(psi_t, K)]
    [t.start() for t in thrds]        
    [t.join() for t in thrds]           # Curriculum learning with multi-threading

    # Freeze the shallowest active layer
    for param in f_S[psi_t].parameters():
        param.requires_grad = False

    # Update curriculum features with forward-propagated ones
    pair_h['curr'] = feature_cache(x, f_S, pair_h['curr'], start_k=psi_t)

student = merge_layers(f_S)             # Merge layers into a full student model
student = attach_lora(student)          # Attach LoRA adapters to student model
short_recover(student)                  # Apply short recovery

\end{lstlisting}
\caption{PyTorch-like pseudocode of layer-wise curriculum learning with feature caching using a multi-threading strategy. It illustrates the detailed implementation and execution workflow.}
\label{alg:curriculum_know_transfer}
\end{algorithm*}


